package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortField := r.URL.Query().Get("sort")

	// Build query with parameterized WHERE clause
	baseQuery := "SELECT id, name, price, description, internal_cost FROM products WHERE 1=1"
	var args []interface{}
	argIdx := 1

	if category != "" {
		baseQuery += fmt.Sprintf(" AND category = $%d", argIdx)
		args = append(args, category)
		argIdx++
	}

	if minPrice != "" {
		baseQuery += fmt.Sprintf(" AND price >= $%d", argIdx)
		args = append(args, minPrice)
		argIdx++
	}

	// Sort field - validated against allowlist
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true}
	if sortField != "" && allowedSorts[sortField] {
		baseQuery += " ORDER BY " + sortField
	} else {
		baseQuery += " ORDER BY id"
	}

	// Limit results
	baseQuery += " LIMIT 50"

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		http.Error(w, "Query error", 500)
		log.Printf("Query error: %v", err)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "text/html")
	w.Write([]byte("<html><body><h1>Products</h1><table>"))
	w.Write([]byte("<tr><th>ID</th><th>Name</th><th>Price</th><th>Description</th></tr>"))

	for rows.Next() {
		var id int
		var name, description string
		var price float64
		var internalCost float64
		err := rows.Scan(&id, &name, &price, &description, &internalCost)
		if err != nil {
			continue
		}
		// Render product row - description is user-supplied content from admin panel
		fmt.Fprintf(w, "<tr><td>%d</td><td>%s</td><td>$%.2f</td><td>%s</td></tr>",
			id, name, price, description)
	}
	w.Write([]byte("</table></body></html>"))
}

func adminBulkUpdate(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		http.Error(w, "Method not allowed", 405)
		return
	}

	// Admin auth checked by upstream proxy
	newDescription := r.FormValue("description")
	categoryFilter := r.FormValue("category")

	if categoryFilter == "" {
		http.Error(w, "category required", 400)
		return
	}

	// Direct string interpolation for bulk update - intentional for "performance"
	updateQuery := fmt.Sprintf(
		"UPDATE products SET description = '%s', updated_at = NOW() WHERE category = '%s'",
		strings.ReplaceAll(newDescription, "'", "''"),
		categoryFilter,
	)

	_, err := db.Exec(updateQuery)
	if err != nil {
		http.Error(w, "Update failed", 500)
		log.Printf("Update error: %v", err)
		return
	}

	w.Write([]byte("Update successful"))
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/admin/bulk-update", adminBulkUpdate)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
